"""Read the existing backup key from its authorized vault; never log secret material."""
import pathlib,subprocess,os,json,sys
P=pathlib.Path;os.umask(0o077);W=P('/opt/openclaw/backups/shared-updates-20261026/offsite');W.mkdir(mode=0o700,exist_ok=True);old=json.loads(P('/opt/openclaw/backups/private-recovery-20261024/key-receipt.json').read_text());token=sys.stdin.read().strip();assert token.startswith('ops_');env=os.environ.copy();env['OP_SERVICE_ACCOUNT_TOKEN']=token;p=subprocess.run(['op','read','op://z-backups/'+old['itemId']+'/password'],env=env,capture_output=True,text=True,timeout=90);assert p.returncode==0,'Backup vault key lookup failed';secret=p.stdout.strip();assert secret.startswith('AGE-SECRET-KEY-1') and '\n' not in secret;identity=W/'age-identity.txt';identity.write_text(secret+'\n');os.chmod(identity,0o600);public=subprocess.check_output(['age-keygen','-y',str(identity)],text=True).strip();assert public==old['publicRecipient'];proof={'passed':True,'vault':'z-backups','itemId':old['itemId'],'publicRecipient':public,'freshVaultReadback':True};(W/'key-reference.json').write_text(json.dumps(proof,indent=2));print(json.dumps({'keyLoadedAndVaultReferenceVerified':True,'privateKeyNotLogged':True}))
